using Microsoft.AspNetCore.Components;
using Microsoft.JSInterop;

namespace sv_fc4c2ae1b0fb48fda58972ad532e4451.Components;

public sealed class InfiniteScrollInterop : IAsyncDisposable
{
    internal const string ModulePath = "./Components/InfiniteScrollList.razor.js";
    internal const string ObserveMethod = "observe";
    internal const string DisposeMethod = "dispose";

    private readonly IJSRuntime _js;
    private IJSObjectReference? _module;

    public InfiniteScrollInterop(IJSRuntime js) => _js = js;

    private async ValueTask<IJSObjectReference> GetModuleAsync()
        => _module ??= await _js.InvokeAsync<IJSObjectReference>("import", ModulePath);

    public async ValueTask ObserveAsync(ElementReference sentinel, DotNetObjectReference<object> dotNetRef)
    {
        var module = await GetModuleAsync();
        await module.InvokeVoidAsync(ObserveMethod, sentinel, dotNetRef);
    }

    public async ValueTask DisposeAsync()
    {
        try
        {
            if (_module is not null)
            {
                await _module.InvokeVoidAsync(DisposeMethod);
                await _module.DisposeAsync();
            }
        }
        catch (JSDisconnectedException) { }
    }
}

const ON_SENTINEL_VISIBLE = "OnSentinelVisible";

let observer;

export function observe(sentinel, dotNetRef) {
    dispose();

    observer = new IntersectionObserver(async (entries) => {
        if (entries[0].isIntersecting) {
            try {
                await dotNetRef.invokeMethodAsync(ON_SENTINEL_VISIBLE);
            } catch { /* circuit disconnected */ }
        }
    });

    observer.observe(sentinel);
}

export function dispose() {
    if (observer) {
        observer.disconnect();
        observer = null;
    }
}

@typeparam TItem
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="infinite-scroll-container">
    @foreach (var item in Items)
    {
        @ChildContent(item)
    }

    @if (HasMore)
    {
        <div @ref="_sentinelRef" class="sentinel">
            @if (_isLoading)
            {
                <div class="spinner"></div>
            }
        </div>
    }
</div>

@code {
    private ElementReference _sentinelRef;
    private InfiniteScrollInterop? _interop;
    private DotNetObjectReference<InfiniteScrollList<TItem>>? _dotNetRef;
    private bool _isLoading;

    [Parameter, EditorRequired]
    public IReadOnlyList<TItem> Items { get; set; } = [];

    [Parameter]
    public bool HasMore { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnLoadMore { get; set; }

    [Parameter, EditorRequired]
    public RenderFragment<TItem> ChildContent { get; set; } = default!;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender && HasMore)
        {
            await StartObservingAsync();
        }
    }

    private bool _wasHasMore;

    protected override void OnParametersSet()
    {
        // Track transitions from !HasMore → HasMore so we can re-observe.
        // Also track when loading finishes so sentinel re-renders.
        _wasHasMore = HasMore;
    }

    private async Task StartObservingAsync()
    {
        _interop = new InfiniteScrollInterop(JS);
        _dotNetRef = DotNetObjectReference.Create(this);
        await _interop.ObserveAsync(_sentinelRef, DotNetObjectReference.Create<object>(this));
    }

    [JSInvokable("OnSentinelVisible")]
